def transform(grid):
    """Extend diagonal rays outward from each 2x2 block of 2s,
    rotating the four surrounding seed colors clockwise."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[i][j] == 2 for i, j in ((r, c), (r, c+1), (r+1, c), (r+1, c+1))):
                blocks.append((r, c))
    for r, c in blocks:
        # Seed locations and outward directions: NW, NE, SW, SE.
        positions = [(r-1, c-1), (r-1, c+2), (r+2, c-1), (r+2, c+2)]
        seeds = [grid[i][j] if 0 <= i < h and 0 <= j < w else 0 for i, j in positions]
        # Clockwise movement of seed colors: NW->NE, NE->SE, SE->SW, SW->NW.
        colors = [seeds[2], seeds[0], seeds[3], seeds[1]]
        directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        for (i, j), color, (di, dj) in zip(positions, colors, directions):
            while 0 <= i < h and 0 <= j < w:
                if grid[i][j] == 2:
                    break
                out[i][j] = color
                # Stop when the ray first reaches the one-cell halo of a different 2x2 block.
                if any((rr, cc) != (r, c) and rr - 1 <= i <= rr + 2 and cc - 1 <= j <= cc + 2
                       for rr, cc in blocks):
                    break
                i += di
                j += dj
    return out

